 const NETPER=5;
 function networkView(){return `<div class="content">${heading('Network / Search','The colleagues you count on, the ones you’ve worked with, and the people PsyAlliance thinks you should know.',btn('Invite a colleague','invite','primary','plus'))}<div class="view-tabs"><button class="${state.networkTab==='circle'?'active':''}" data-action="network-tab:circle">Your circle</button><button class="${state.networkTab==='directory'?'active':''}" data-action="network-tab:directory">Find colleagues ${icon('search')}</button></div>${state.networkTab==='circle'?`<section class="panel network-overview">${circleMarkup()}<div><h2>Your network, built around you.</h2><p>Every relationship has a place. You choose who you trust; shared work and useful perspectives help the rest take shape.</p>${circleLegend()}${btn('Search the whole network','network-tab:directory','secondary wide','search')}</div></section><div class="relationship-groups">${tiers.slice(0,3).map((t,i)=>{let all=people.filter(p=>relation(p.id)===i);if(i===2){const rank=id=>{const k=state.suggested.indexOf(id);return k<0?1e6:k;};all=all.sort((a,b)=>rank(a.id)-rank(b.id)).slice(0,10);}const pages=Math.max(1,Math.ceil(all.length/NETPER)),pg=Math.min(Math.max(1,state.netPage[t.key]||1),pages),shown=all.slice((pg-1)*NETPER,pg*NETPER);return `<section class="panel relationship-group net-${t.key}" id="net-${t.key}"><header><h2><span class="tier-dot relation-${t.key}"></span>${t.name}</h2>${badge(all.length,'gray')}</header>${i===2&&all.length?'<p class="net-caption">Up to 10, best fit first.</p>':''}${shown.map(p=>netRow(p,i)).join('')||`<p class="net-empty">${networkEmpty(i)}</p>`}${pages>1?`<div class="net-pager"><button type="button" data-action="net-page:${t.key}:${pg-1}" aria-label="Previous ${t.name}" ${pg===1?'disabled':''}>${icon('chevron-left')}</button><span>Page ${pg} of ${pages}</span><button type="button" data-action="net-page:${t.key}:${pg+1}" aria-label="Next ${t.name}" ${pg===pages?'disabled':''}>${icon('chevron-right')}</button></div>`:''}</section>`;}).join('')}</div>`:directoryContent()}${footer()}</div>`;}
 function splitPanel(title,desc,ico,items,renderRow,direction,caption=''){return `<section class="panel direction-${direction}"><header class="list-section-header"><span class="action-icon">${icon(ico)}</span><div>${caption?`<span class="direction-caption">${caption}</span>`:''}<h2>${title}</h2><p>${desc}</p></div>${badge(items.length,'gray')}</header><div class="list-section-body">${items.map(renderRow).join('')||'<div class="no-results">No arrangements in this view.</div>'}</div></section>`;}
 function incomingCoverStatus(p){const pending=p.clients.filter(c=>!c.assignee&&c.requests.some(r=>r.person==='me'&&['awaiting','discussing'].includes(r.status))),assigned=p.clients.filter(c=>c.assignee==='me'),unready=assigned.filter(c=>c.status!=='ready');return {pending,assigned,unready};}
 function referralNext(r){if(r.status==='withdrawn')return {text:'Withdrawn. History is kept.'};if(r.status==='placed')return {text:r.placedElsewhere?'Placed with another colleague.':`Placed with ${person(r.placedWith).name}.`,done:true};if(r.owner!=='me'){const mine=r.requests.find(q=>q.person==='me');return mine?.status==='awaiting'?{text:'Say whether you can help.',act:'Reply'}:mine?.status==='discussing'?{text:'Finish the conversation, then answer.',act:'Reply'}:mine?.status==='interested'?{text:'Wait for the sender to confirm the placement.'}:{text:'You said you are not available.'};}const interested=r.requests.filter(q=>q.status==='interested'),pending=r.requests.filter(q=>['awaiting','discussing'].includes(q.status));return interested.length?{text:`Choose who to place the client with (${interested.length} interested).`,act:'Review replies'}:pending.length?{text:`Wait for ${pending.length===1?person(pending[0].person).name:pending.length+' colleagues'} to reply.`}:{text:'No open offers. Ask another colleague or withdraw.',act:'Ask another'};}
 function planNext(p){if(p.status!=='active')return {text:p.status==='completed'?'Completed.':'Cancelled.',done:true};const incoming=p.owner!=='me';if(incoming){const my=incomingCoverStatus(p);return my.pending.length?{text:`Reply to ${my.pending.length} invitation${my.pending.length===1?'':'s'}.`,act:'Reply'}:my.unready.length?{text:'Wait for the organiser to confirm the handover.'}:my.assigned.length?{text:'Your handover arrangements are ready.',done:true}:{text:'Nothing to do.'};}const needs=coverNeeds(p,true,false).filter(x=>!x.wait);if(needs.length)return {text:String(needs[0].title).replace(/<[^>]+>/g,'').replace(/&amp;/g,'&')+'.',act:'Open plan'};const waiting=p.clients.filter(c=>!c.assignee).length;return waiting?{text:`Waiting on replies for ${waiting} client${waiting===1?'':'s'}.`}:{text:'Everything is ready. Complete the arrangement when you are back.',act:'Open plan'};}
 const nextLine=(n,id)=>`<small class="arrangement-next ${n.act?'needs-action':''}">${icon(n.done?'circle-check':'corner-down-right')}<span><b>${n.done?'Done':'Next'}:</b> ${escape(n.text)}</span></small>`;
 function planRow(p){const n=counts(p),incoming=p.owner!=='me',my=incomingCoverStatus(p),pending=my.pending.length,myHandover=my.unready.length,summary=p.status!=='active'?p.status==='completed'?'Arrangement completed.':'Arrangement cancelled.':incoming?[`${my.assigned.length} client${my.assigned.length===1?'':'s'} accepted by you.`,pending?`${pending} invitation${pending===1?'':'s'} still need${pending===1?'s':''} your reply.`:myHandover?`${myHandover} handover${myHandover===1?'':'s'} awaiting the organiser’s confirmation.`:my.assigned.length?'Your handover arrangements are ready.':'No cover commitment.'].join(' '):unfinishedSummary(p),status=p.status!=='active'?p.status==='completed'?'Completed':'Cancelled':incoming?pending?'Needs your reply':myHandover?'Handover pending':my.assigned.length?'Ready':'Not covering':n.ready===n.total?'Ready':'Active';const tone=p.status!=='active'?'done':incoming&&pending?'reply':status==='Ready'?'ready':'active';return `<article class="arrangement-row row-${tone}" data-action="plan:${p.id}"><span class="plan-date"><small>${shortMonth(p.start)}</small><b>${Number(p.start.split('-')[2])}</b></span><span class="arrangement-main"><strong><button class="text-link" data-action="plan:${p.id}">${escape(p.name)}</button></strong><small>${incoming?`Plan by ${person(p.owner).name} · `:'Your plan · '}${rangeLabel(p)}${incoming?'':` · ${p.clients.length} client${p.clients.length===1?'':'s'}`}</small>${(()=>{const nx=planNext(p);return nextLine(nx)})()}</span><span class="arrangement-side">${badge(status,pending&&incoming?'gold':p.status==='active'?'':'gray')}${iconButton('chevron-right',`plan:${p.id}`,'View cover plan')}</span></article>`;}
 function draftBanner(type){const list=type==='peer'?(state.peerDraft?[state.peerDraft]:[]):[...(state[type==='cover'?'coverDrafts':'referralDrafts']||[])].sort((x,y)=>String(y.updatedAt||'').localeCompare(String(x.updatedAt||'')));return list.map(d=>{const label=type==='cover'?'Cover':type==='referral'?'Referral':'Consult',name=type==='cover'?d.name:type==='referral'?d.focus:d.title,detail=type==='cover'?`${d.clients?.length||0} client${d.clients?.length===1?'':'s'} added`:type==='referral'?d.focus?stateName(d.state):'Add the client’s requirements':d.title?'Question saved':'Add your question',key=type==='peer'?'peer':`${type}:${d.draftId}`;return `<div class="draft-banner">${icon('file-pen-line')}<span><strong>${escape(name||`Unfinished ${label} draft`)}</strong><small>Saved draft · Not sent · ${escape(detail)}</small></span><div class="draft-actions">${btn('Continue draft',type==='peer'?'peer-start':'draft-open:'+key,'secondary small')}${btn('Delete draft','draft-delete:'+key,'text small','trash-2')}</div></div>`;}).join('');}
 function deleteSavedDraft(value){const [type,did]=String(value).split(':');if(type==='peer'){state.peerDraft=null;if(workflow?.type==='peer')workflow=null;persist();return true;}if(!['cover','referral'].includes(type))return false;const key=type==='cover'?'coverDrafts':'referralDrafts';state[key]=(state[key]||[]).filter(d=>d.draftId!==did);if(workflow?.type===type&&workflow.draftId===did)workflow=null;persist();return true;}
 function visiblePlans(){return state.plans.filter(p=>state.coverFilter==='all'||state.coverFilter==='active'&&p.status==='active'||state.coverFilter==='past'&&p.status!=='active');}
 function coverView(){const ps=visiblePlans();return `<div class="content">${heading('Cover','Arrange cover for your clients, or respond to a colleague’s request for help.',btn('Arrange cover for my clients','cover-start','primary','plus'))}<div class="toolbar"><div class="filter-pills">${[['all','All'],['active','Active'],['past','Completed']].map(([k,t])=>`<button class="${state.coverFilter===k?'active':''}" data-action="cover-filter:${k}">${t}</button>`).join('')}</div><div class="layout-toggle">${[['list','list','List'],['calendar','calendar-days','Calendar']].map(([k,i,t])=>`<button class="${state.coverLayout===k?'active':''}" data-action="cover-layout:${k}">${icon(i)}${t}</button>`).join('')}</div></div>${draftBanner('cover')}${state.coverLayout==='calendar'?calendarView(ps):`<div class="split-lists">${splitPanel('Colleagues covering your clients','You make the plan, choose who to ask and confirm each handover.','shield-check',ps.filter(p=>p.owner==='me'),planRow,'outgoing','WHEN YOU’RE AWAY')}${splitPanel('You covering colleagues’ clients','A colleague makes the plan. You reply to requests and provide the cover you agree to.','inbox',ps.filter(p=>p.owner!=='me'),planRow,'incoming','WHEN A COLLEAGUE IS AWAY')}</div>`}<section class="invite-banner"><span class="invite-mark">${icon('shield-check')}</span><div><h3>An acceptance is the start of a dependable arrangement.</h3><p>Confirm the handover before marking a client ready.</p></div>${btn('View checklist','resource:1','secondary small','arrow-up-right')}</section>${footer()}</div>`;}
 function calendarPlans(ps,from,to=from){return ps.filter(p=>p.status!=='cancelled'&&p.start<=to&&(!p.end||p.end>=from)&&(state.calendarScope==='own'?p.owner==='me':state.calendarScope==='colleagues'?p.owner!=='me':true)).sort((a,b)=>a.start.localeCompare(b.start)||a.id-b.id);}
