 if(tab==='colleagues'){const ids=[...new Set(p.clients.flatMap(c=>c.requests.map(r=>r.person)))];body+=`<div class="tracking-colleagues">${ids.map(id=>`<article class="tracking-colleague"><header>${avatar(person(id))}<div><h3>${person(id).name}</h3>${id==='me'?'':relationBadge(id)}</div>${btn('Profile',`profile:${id}`,'secondary small')}</header>${p.clients.filter(c=>c.requests.some(r=>r.person===id)).map(c=>{const r=c.requests.find(r=>r.person===id);return `<div class="colleague-client-row"><span><strong>${c.label} · ${escape(c.focus)}</strong><small>${stateName(c.state)} · ${settingLabel(c.setting)}</small></span>${badge(c.assignee===id?caseStatus(c):requestLabel(r.status),c.assignee===id?'':'gray')}</div>`;}).join('')}</article>`).join('')}</div>`;}
 if(tab==='history')body+=`<div class="timeline">${p.history.map(h=>`<div class="timeline-item">${escape(h.text)}<small>${new Date(h.at).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'})}</small></div>`).join('')}</div>`;
