 function globalResults(q){const scope=state.searchScope||'all',items=[...state.threads.map(t=>({scope:'messages',title:t.group?t.context:`${person(t.person).name} · ${t.context}`,desc:`Conversation · ${t.messages.at(-1)?.text||''}`,action:`thread:${t.id}`,ico:'messages-square'})),...people.map(p=>({scope:'colleagues',title:p.name,desc:`Colleague · ${p.city}, ${p.state}${p.specialties?.length?` · ${p.specialties.slice(0,2).join(', ')}`:''}`,action:`profile:${p.id}`,ico:'user-round'})),...state.plans.map(p=>({scope:'cover',title:p.name,desc:`Cover · ${rangeLabel(p)}`,action:`plan:${p.id}`,ico:'shield-check'})),...state.referrals.map(r=>({scope:'referrals',title:r.title||needSummary(r),desc:`Referral · ${stateName(r.state)}`,action:`referral:${r.id}`,ico:'arrow-right-left'})),...discussions.map(d=>({scope:'consult',title:d.title,desc:`Consult · ${discussionTags(d).slice(0,2).join(', ')}`,action:`discussion:${d.id}`,ico:'message-circle-more'})),...resources.map(r=>({scope:'library',title:r.title,desc:`Library · ${r.category}`,action:`resource:${r.id}`,ico:'file-text'}))],terms=q.toLowerCase().split(',').map(x=>x.trim()).filter(Boolean),hits=items.filter(i=>(scope==='all'||i.scope===scope)&&terms.every(t=>`${i.title} ${i.desc}`.toLowerCase().includes(t))).slice(0,scope==='all'?8:12),more=scope==='colleagues'?`<button class="global-result" data-action="directory">${icon('users-round')}<span><h3>Open Network / Search</h3><p>Filter colleagues by state, specialism, availability and more.</p></span></button>`:'';return hits.map(i=>`<button class="global-result" data-action="${i.action}">${icon(i.ico)}<span><h3>${escape(i.title)}</h3><p>${escape(i.desc)}</p></span></button>`).join('')+more||'<p class="no-results">No results. Try a name or topic.</p>';}
