 function openThread(id){cleanupRecorder();const t=state.threads.find(t=>t.id===id);if(!t)return;const wasView=state.view,wasModal=state.modal==='directory'?'directory':null,wasTab=state.networkTab;closeModal(false,true);if(wasView!=='messages'){const names={home:'The Hub',cover:'Cover',referrals:'Referrals',consult:'Consult',network:wasTab==='directory'?'search results':'Network',library:'Library'};state.messageOrigin={view:wasView,modal:wasModal,tab:wasTab,label:wasModal?'search results':(names[wasView]||'where you were')};}else if(state.selectedThread!==id)state.messageOrigin=null;state.selectedThread=id;state.inboxPerson=t.person;state.draftAttachment=state.attachmentDrafts[id]||null;state.audioDraft=state.audioDrafts[id]||null;state.view='messages';state.threadOpen=true;state.menuOpen=false;state.chatSearch=false;const hadUnread=t.unread;t.unread=0;persist();render();if(LIVE&&wasView!=='messages'&&env.navigate)env.navigate(VIEW_PATHS.messages);if(LIVE&&hadUnread)env.call('conversation.read',{key:id}).catch(()=>{});}
