  function messagesView(){return `<div class="messages-page ${state.threadOpen?'thread-open':''}"><header class="messages-heading"><h1>Messages ${unreadCount()?`<span class="count-label">${unreadCount()} unread</span>`:''}</h1>${btn('New message','new-message','secondary','square-pen')}</header><div class="message-workspace"><aside class="inbox" aria-label="Conversations"><div class="inbox-tools"><label class="search-field">${icon('search')}<input id="inbox-search" placeholder="Search conversations" aria-label="Search conversations" value="${escape(state.messageSearch)}"></label><div class="inbox-filters">${['All','Unread','Cover','Referral','Group'].map(f=>`<button data-action="inbox-filter:${f}" class="${state.inboxFilter===f?'active':''}">${f}</button>`).join('')}</div></div><div class="inbox-list" id="inbox-list">${inboxList()}</div><div class="inbox-note">${LIVE&&!PREVIEW?'Private, in-network messaging':SBX?'Sandbox · Delivery is simulated':'Browser-local preview · Delivery is simulated'}</div></aside><section class="chat-pane" aria-label="Conversation">${threadContent()}</section></div></div>`;}
 function threadActivity(t){const m=t.messages.at(-1),stamp=Date.parse(m?.createdAt||t.activityAt||'');if(Number.isFinite(stamp))return stamp;const match=String(m?.time||t.time||'').match(/^(\d{1,2}):(\d{2})$/);if(!match)return 0;const d=new Date();if(t.time==='Yesterday')d.setDate(d.getDate()-1);d.setHours(Number(match[1]),Number(match[2]),0,0);return d.getTime();}
 const threadName=t=>t.group?t.context:person(t.person).name;
